# REASONING: Populate the monthly tracker using the annual patient lab report data and standing orders.

from docx import Document
from openpyxl import load_workbook
import re
from collections import defaultdict

PATIENT_TO_PROVIDER = {
    "Cash Stonewater": "Dr. Joe",
    "Fred Fintmore": "Dr. Joe",
    "Betty Brite": "Dr. Johnson",
    "Tina Lee Bell": "Dr. Johnson",
    "Eric Bird": "Dr. Lee",
    "Homer Sandson": "Dr. Lee",
    "Jessica Rashmore": "Dr. Michael",
}

def parse_num(v):
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v)
    m = re.search(r'-?\d+(?:\.\d+)?', str(v))
    return float(m.group()) if m else None

def normalize_key(k):
    k = str(k).strip().lower()
    k = k.replace("/", "_").replace(" ", "_").replace("-", "_")
    return k

def extract_docx_tables(docx_path):
    doc = Document(docx_path)
    data = defaultdict(dict)

    # Parse paragraphs for simple "Patient: ..." / key-value patterns
    current = None
    for p in doc.paragraphs:
        s = p.text.strip()
        if not s:
            continue
        if s in PATIENT_TO_PROVIDER:
            current = s
            continue
        if current:
            m = re.match(r'([^:]+):\s*(.+)$', s)
            if m:
                k = normalize_key(m.group(1))
                v = m.group(2).strip()
                data[current][k] = v

    # Parse tables if present; use first column as labels and header row as months
    for t in doc.tables:
        if not t.rows:
            continue
        headers = [c.text.strip() for c in t.rows[0].cells]
        for r in t.rows[1:]:
            cells = [c.text.strip() for c in r.cells]
            if not cells:
                continue
            if cells[0] in PATIENT_TO_PROVIDER:
                current = cells[0]
                data[current]["patient_name"] = current
                continue
            if current and len(cells) >= 2:
                key = normalize_key(cells[0])
                # keep all non-empty month values
                for i in range(1, min(len(cells), len(headers))):
                    if cells[i]:
                        data[current][f"{key}_{normalize_key(headers[i])}"] = cells[i]
    return data

def compute_orders(labs, provider, prior_orders=None):
    prior_orders = list(prior_orders or [])
    orders = []

    # Pull common values from annual/monthly data if present
    hgb = parse_num(labs.get("hgb") or labs.get("hemoglobin"))
    ca = parse_num(labs.get("calcium"))
    phos = parse_num(labs.get("phosphorus") or labs.get("phos"))
    ktv = parse_num(labs.get("kt_v") or labs.get("ktv") or labs.get("kt/v"))

    # KT/V rule
    if ktv is not None and ktv < 1.2:
        orders.append("Repeat lab work in 1 month due to KT/V < 1.2")

    # Calcium rule
    if ca is not None and 7.9 <= ca <= 8.4:
        orders.append("TUMS 2 tabs by mouth 3 times a week")

    # Anemia rule
    if hgb is not None and hgb < 10.0:
        orders.append("Start Aranesp 10 mcg IVP each treatment")
    else:
        # If already on Aranesp and a dose decrease is needed per protocol, adjust to 10 mcg IVP two times a week
        for o in prior_orders:
            if "Aranesp 10 mcg IVP each treatment" in o:
                orders.append("Aranesp 10 mcg IVP two times a week")
                break

    # Phosphorus binder rules by provider
    if provider in ("Dr. Joe", "Dr. Johnson"):
        if phos is not None and 5.6 <= phos <= 7.4:
            orders.append("Start Renvela 800 mg orally with meals")
        elif phos is not None and 4.0 <= phos <= 5.5:
            orders.append("Continue most recently prescribed Renvela dose without change")
    elif provider in ("Dr. Lee", "Dr. Michael"):
        if phos is not None and 5.5 <= phos <= 7.4:
            orders.append("Start Phoslo 667 mg, 2 tablets orally with each meal")
        elif phos is not None and 4.0 <= phos <= 5.5:
            orders.append("Continue most recently prescribed Phoslo dose without change")

    return orders

def infer_row_headers(ws):
    # Find a row with patient name and MRN headers
    for r in range(1, min(ws.max_row, 20) + 1):
        vals = [ws.cell(r, c).value for c in range(1, ws.max_column + 1)]
        lowered = [str(v).strip().lower() if v is not None else "" for v in vals]
        if any("name" == x or "patient name" == x for x in lowered) and any("mrn" == x for x in lowered):
            headers = {}
            for c, v in enumerate(vals, 1):
                if v is not None:
                    headers[normalize_key(v)] = c
            return r, headers
    return 1, {}

def find_best_col(headers, *needles):
    for k, c in headers.items():
        if all(n in k for n in needles):
            return c
    for k, c in headers.items():
        if any(n in k for n in needles):
            return c
    return None

def update_workbook(xlsx_path, output_path, patient_data):
    wb = load_workbook(xlsx_path)
    ws = wb.active

    header_row, headers = infer_row_headers(ws)
    name_col = find_best_col(headers, "patient", "name") or find_best_col(headers, "name") or 1
    mrn_col = find_best_col(headers, "mrn") or 2

    # Month columns or generic lab columns may exist; map by header name if possible
    for patient, labs in patient_data.items():
        provider = PATIENT_TO_PROVIDER.get(patient, "")
        orders = compute_orders(labs, provider, labs.get("_prior_orders", []))

        # Find existing patient row or append
        row = None
        for r in range(header_row + 1, ws.max_row + 1):
            if str(ws.cell(r, name_col).value).strip() == patient:
                row = r
