        if notes_col is not None:
            ws.cell(row, notes_col).value = "; ".join(orders)
        else:
            # Create a final column if no notes column exists
            ws.cell(row, ws.max_column + 1).value = "; ".join(orders)

    wb.save(output_path)

def main():
    docx_path = "Patient Lab Reports.docx"
    xlsx_path = "Monthly Tracker Patient Lab Results.xlsx"
    output_path = "Monthly Tracker Patient Lab Results_UPDATED.xlsx"

