def greedy_count(N):
    q = N // 25
    rem = N - 25*q
    d = rem // 10
    rem -= 10*d
    p = rem
    return q + d + p

def min_count(N):
    best = 10**9
    for q in range(N//25 + 1):
        for d in range((N-25*q)//10 + 1):
            p = N - 25*q - 10*d
            best = min(best, q+d+p)
    return best

