from typing import List

class TrieNode:
    __slots__ = ("children",)

    def __init__(self):
        self.children = {}


class Solution:
    def longestCommonPrefix(self, arr1: List[int], arr2: List[int]) -> int:
        # Build a trie from all numbers in arr1 using their decimal digits
        root = TrieNode()

        for num in arr1:
            node = root
            for ch in str(num):
                if ch not in node.children:
                    node.children[ch] = TrieNode()
                node = node.children[ch]

        # For each number in arr2, walk the trie as far as possible
        ans = 0
        for num in arr2:
            node = root
            length = 0
            for ch in str(num):
                if ch not in node.children:
                    break
                node = node.children[ch]
                length += 1
            if length > ans:
                ans = length

        return ans
