class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        positives = []
        negatives = []
        zeros = 0

        for x in nums:
            if x > 0:
                positives.append(x)
            elif x < 0:
                negatives.append(x)
            else:
                zeros += 1

        # If there are no non-zero numbers
        if not positives and len(negatives) < 2:
            return 0

        negatives.sort()

        prod = 1
        used = False

        for x in positives:
            prod *= x
            used = True

        # Take negatives in pairs, excluding at most one negative with smallest absolute value
        if len(negatives) >= 2:
            # If odd number of negatives, drop the negative closest to zero (largest value)
            if len(negatives) % 2 == 1:
                negatives.pop()
            for x in negatives:
                prod *= x
                used = True

        return prod if used else 0

