from typing import List

class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        positives = [x for x in nums if x > 0]
        negatives = sorted(x for x in nums if x < 0)

        # If there are no positive numbers and fewer than 2 negatives,
        # the best non-empty subset is either 0 (if any zero exists)
        # or the largest element (which will be negative).
        if not positives and len(negatives) < 2:
            return 0 if 0 in nums else max(nums)

        # If there is an odd number of negatives, drop the one closest to 0.
        if len(negatives) % 2 == 1:
            negatives.pop()

        ans = 1
        for x in positives:
            ans *= x
        for x in negatives:
            ans *= x

        return ans
