import sys
from functools import lru_cache

def main():
    A = list(map(int, sys.stdin.buffer.read().split()))
    if len(A) != 9:
        return

    lines = [
        0b000000111, 0b000111000, 0b111000000,
        0b001001001, 0b010010010, 0b100100100,
        0b100010001, 0b001010100,
    ]
    FULL = (1 << 9) - 1

    def has_line(mask):
        for lm in lines:
            if mask & lm == lm:
                return True
        return False

    @lru_cache(None)
    def solve(tmask, amask, turn, diff):
        used = tmask | amask

        if used == FULL:
            return "Takahashi" if diff > 0 else "Aoki"

        for i in range(9):
            if (used >> i) & 1:
                continue
            bit = 1 << i

            if turn == 0:  # Takahashi
                nt = tmask | bit
                ndiff = diff + A[i]
                if has_line(nt):
                    return "Takahashi"
                if solve(nt, amask, 1, ndiff) == "Takahashi":
                    return "Takahashi"
            else:  # Aoki
                na = amask | bit
                ndiff = diff - A[i]
                if has_line(na):
                    return "Aoki"
                if solve(tmask, na, 0, ndiff) == "Aoki":
                    return "Aoki"

        return "Aoki" if turn == 0 else "Takahashi"

    print(solve(0, 0, 0, 0))

if __name__ == "__main__":
    main()

