import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    adj = [[] for _ in range(N + 1)]
    max_ratio = 0.0

    for _ in range(M):
        u = int(next(it))
        v = int(next(it))
        b = int(next(it))
        c = int(next(it))
        adj[u].append((v, b, c))
        ratio = b / c
        if ratio > max_ratio:
            max_ratio = ratio

    def feasible(x):
        NEG = -1e100
        dp = [NEG] * (N + 1)
        dp[1] = 0.0
        for u in range(1, N + 1):
            du = dp[u]
            if du == NEG:
                continue
            for v, b, c in adj[u]:
                val = du + b - x * c
                if val > dp[v]:
                    dp[v] = val
        return dp[N] >= 0.0

    lo, hi = 0.0, max_ratio
    for _ in range(80):
        mid = (lo + hi) / 2.0
        if feasible(mid):
            lo = mid
        else:
            hi = mid

    print(f"{lo:.16f}")

if __name__ == "__main__":
    solve()
